if($m==='DELETE'){$pdo->prepare('DELETE FROM lecture_photos WHERE id=?')->execute([(int)($d['id']??0)]);json_out(['ok'=>true]);}json_out(['ok'=>false,'error'=>'روش نامعتبر است.'],405);
